      parent: parentOf(present, unitId),
      dependencies_out: present.edges.filter((edge) => edge.from === unitId).map((edge) => ({ to: edge.to, label: edge.label })),
      dependencies_in: present.edges.filter((edge) => edge.to === unitId).map((edge) => ({ from: edge.from, label: edge.label })),
